    mu = compute_mobius(K)
    total = 0
    for d in range(1, K + 1):
        m = K // d
        s = 0
        for k in range(1, m + 1):
            term = mu[k] * ( (m // k) ) ** 3
            s += term
        total += d * s
    print(total)

